using Essco.Application.Products;
using Essco.Domain.Products;
namespace Essco.Infrastructure.Data; public sealed class UnavailableProductRepository : IProductRepository { public ValueTask<IReadOnlyCollection<Product>> ListAsync(ProductFilter f, CancellationToken t) => ValueTask.FromResult<IReadOnlyCollection<Product>>([]); public ValueTask<IReadOnlyCollection<AutomaticDiscount>> ListDiscountsAsync(CancellationToken t) => ValueTask.FromResult<IReadOnlyCollection<AutomaticDiscount>>([]); public ValueTask<IReadOnlyCollection<PriceList>> ListPriceListsAsync(CancellationToken t) => ValueTask.FromResult<IReadOnlyCollection<PriceList>>([]); private static InvalidOperationException E() => new("Artículos no están configurados."); public ValueTask<bool> SaveDiscountAsync(AutomaticDiscount x, bool n, CancellationToken t) => ValueTask.FromException<bool>(E()); public ValueTask<bool> DeleteDiscountAsync(string c, CancellationToken t) => ValueTask.FromException<bool>(E()); public ValueTask<int> SavePriceListAsync(PriceList x, bool n, CancellationToken t) => ValueTask.FromException<int>(E()); public ValueTask<bool> SetPriceListInactiveAsync(int i, bool x, CancellationToken t) => ValueTask.FromException<bool>(E()); }
